def visual_panel(i):
    title,nodes,prompt=SCENES[i]
    # Mobile uses a vertical reading order; the same labelled shapes keep their meaning.
    ys=[48,160,272,384,496]
    colors=['data','system','system','evidence','evidence']
    shapes=[]
    for j,((label,sub,ex),y) in enumerate(zip(nodes,ys)):
        shapes.append(f'<g class="scene-node {colors[j]} {"active" if j==0 else ""}" data-node="{j}"><rect x="35" y="{y}" width="290" height="76" rx="15"/><circle cx="61" cy="{y+24}" r="12"/><text x="61" y="{y+29}" class="node-number">{j+1}</text><text x="88" y="{y+29}" class="node-label" data-label="{E(label)}">{E(label)}</text><text x="88" y="{y+53}" class="node-sub" data-label="{E(sub)}">{E(sub)}</text></g>')
        if j<4: shapes.append(f'<path class="scene-arrow" d="M180 {y+77} V{ys[j+1]-8}" marker-end="url(#arrow-{i})"/>')
    svg=f'<svg class="scene-svg" viewBox="0 0 360 600" role="img" aria-label="{E(title)}"><title>{E(title)}</title><defs><marker id="arrow-{i}" markerWidth="8" markerHeight="8" refX="6" refY="3" orient="auto"><path d="M0 0 L6 3 L0 6" fill="#6a8780"/></marker></defs>{"".join(shapes)}</svg>'
    buttons=''.join(f'<button type="button" class="scene-choice {"selected" if j==0 else ""}" data-step="{j}" aria-pressed="{"true" if j==0 else "false"}"><span>{j+1:02}</span> {E(n[0])}</button>' for j,n in enumerate(nodes))
    data=''.join(f'<p data-explain="{j}" {"" if j==0 else "hidden"}>{E(n[2])}</p>' for j,n in enumerate(nodes))
    return f'''<div class="visual-scene" data-scene="{i}"><div class="eyebrow">СМОТРИ → НАЖМИ → ВОССТАНОВИ</div><h3>{E(title)}</h3><p class="visual-instruction">Выбери шаг. Подсветка покажет его место, а пояснение — что происходит. Затем скрой подписи и попробуй восстановить цепочку.</p><div class="scene-layout"><div class="scene-picture">{svg}<div class="visual-legend"><span class="legend-data">Данные / вход</span><span class="legend-system">Обработка / система</span><span class="legend-evidence">Результат / проверка</span></div></div><div class="scene-content"><div class="scene-choices">{buttons}</div><div class="scene-explanation" aria-live="polite">{data}</div><div class="scene-actions"><button type="button" class="scene-next">Следующий шаг →</button><button type="button" class="secondary scene-hide">Скрыть подписи</button></div><p class="scene-prompt">{E(prompt)}</p><details class="recall"><summary>Восстановить порядок без подсказки</summary><p>Выбирай названия в порядке стрелок. Ошибка оставит место для новой попытки.</p><div class="recall-options">{''.join(f'<button type="button" class="secondary" data-recall="{j}">{E(nodes[j][0])}</button>' for j in [2,4,0,3,1])}</div><p class="recall-result" aria-live="polite">0 из 5 шагов восстановлено</p><button type="button" class="secondary recall-reset">Начать заново</button></details><p class="model-note">Учебная модель. Это схема понятий, а не запись работы настоящего инструмента.</p></div></div></div>'''
